# Per-row analysis: in each row, most common becomes least common's value, least common becomes 0
from collections import Counter

def transform_row(row):
    counts = Counter(row)
    most_common_val = counts.most_common(1)[0][0]
    least_common_val = counts.most_common()[-1][0]

    new_row = []
    for cell in row:
        if cell == most_common_val:
            new_row.append(least_common_val)
        elif cell == least_common_val:
            new_row.append(0)
        else:
            new_row.append(cell)
    return new_row

def transform_grid(grid):
    return [transform_row(row) for row in grid]

